1	"use client";
2	
3	import { type FormEvent, useMemo, useState } from "react";
4	
5	import {
6	  ArrowLeft,
7	  CheckCircle2,
8	  CircleCheck,
9	  CircleDot,
10	  CircleX,
11	  LifeBuoy,
12	  MessageSquare,
13	  Plus,
14	  Search,
15	  Send,
16	  X,
17	} from "lucide-react";
18	import { toast } from "sonner";
19	
20	import { CollectionHeader } from "@/components/collection-header";
21	import { DataTableFilter, DataTableHeader, DataTableToolbar } from "@/components/data-table-controls";
22	import { EmptyState } from "@/components/empty-state";
23	import { MetricCard } from "@/components/metric-card";
24	import { SheetActions } from "@/components/sheet-actions";
25	import { TablePagination } from "@/components/table-pagination";
26	import { Badge } from "@/components/ui/badge";
27	import { Button } from "@/components/ui/button";
28	import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
29	import { Field, FieldDescription, FieldGroup, FieldLabel } from "@/components/ui/field";
30	import { Input } from "@/components/ui/input";
31	import { Select, SelectContent, SelectGroup, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
32	import { Sheet, SheetContent, SheetDescription, SheetHeader, SheetTitle } from "@/components/ui/sheet";
33	import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
34	import { Textarea } from "@/components/ui/textarea";
35	
36	type Status = "open" | "resolved" | "closed";
37	type Ticket = {
38	  id: string;
39	  category: string;
40	  subject: string;
41	  description: string;
42	  status: Status;
43	  comments: string[];
44	  updatedAt: string;
45	};
46	
47	const categories = ["Cuenta y acceso", "Publicación y canales", "Facturación y plan", "Otro problema"];
48	const initialTickets: Ticket[] = [
49	  {
50	    id: "SUP-1042",
51	    category: "Publicación y canales",
52	    subject: "La imagen no se muestra en la vista previa",
53	    description: "El archivo adjunto aparece vacío aunque está disponible en la biblioteca.",
54	    status: "open",
55	    comments: ["Estamos revisando el archivo y la conexión con el canal."],
56	    updatedAt: "4 ago 2026",
57	  },
58	  {
59	    id: "SUP-1038",
60	    category: "Cuenta y acceso",
61	    subject: "Necesito actualizar el rol de una persona",
62	    description: "Quiero permitir que una integrante administre los canales.",
63	    status: "resolved",
64	    comments: ["El rol ya se puede actualizar desde Teams."],
65	    updatedAt: "29 jul 2026",
66	  },
67	  {
68	    id: "SUP-1021",
69	    category: "Facturación y plan",
70	    subject: "Consulta sobre el límite de publicaciones",
71	    description: "¿Los borradores consumen el límite mensual?",
72	    status: "closed",
73	    comments: ["Los borradores no consumen el límite."],
74	    updatedAt: "12 jul 2026",
75	  },
76	];
77	
78	const statusLabel: Record<Status, string> = { open: "Abierto", resolved: "Resuelto", closed: "Cerrado" };
79	const statusVariant: Record<Status, "info" | "success" | "secondary"> = {
80	  open: "info",
81	  resolved: "success",
82	  closed: "secondary",
83	};
84	
85	function RequiredMark() {
86	  return (
87	    <span aria-hidden="true" className="text-destructive">
88	      *
89	    </span>
90	  );
91	}
92	
93	function TicketSheet({
94	  open,
95	  onOpenChange,
96	  onCreate,
97	}: {
98	  open: boolean;
99	  onOpenChange: (open: boolean) => void;
100	  onCreate: (ticket: Ticket) => void;
101	}) {
102	  const [category, setCategory] = useState("");
103	  const [subject, setSubject] = useState("");
104	  const [description, setDescription] = useState("");
105	  const complete = Boolean(category && subject.trim() && description.trim());
106	
107	  function close() {
108	    setCategory("");
109	    setSubject("");
110	    setDescription("");
111	    onOpenChange(false);
112	  }
113	
114	  function submit(event: FormEvent<HTMLFormElement>) {
115	    event.preventDefault();
116	    if (!complete) {
117	      toast.error("Completa todos los campos obligatorios.");
118	      return;
119	    }
120	    onCreate({
121	      id: `SUP-${Date.now().toString().slice(-4)}`,
122	      category,
123	      subject: subject.trim(),
124	      description: description.trim(),
125	      status: "open",
126	      comments: [],
127	      updatedAt: "ahora",
128	    });
129	    toast.success("Caso creado.");
130	    close();
131	  }
132	
133	  return (
134	    <Sheet open={open} onOpenChange={(next) => (next ? onOpenChange(true) : close())}>
135	      <SheetContent className="w-full gap-0 p-0 sm:max-w-xl" side="right">
136	        <SheetHeader className="border-b">
137	          <SheetTitle>Nuevo caso de soporte</SheetTitle>
138	          <SheetDescription>Describe lo que necesitas y conserva la conversación en este mismo caso.</SheetDescription>
139	        </SheetHeader>
140	        <form className="flex min-h-0 flex-1 flex-col" noValidate onSubmit={submit}>
141	          <div className="flex min-h-0 flex-1 flex-col gap-5 overflow-y-auto p-4">
142	            <FieldGroup>
143	              <Field>
144	                <FieldLabel htmlFor="support-category">
145	                  Categoría <RequiredMark />
146	                </FieldLabel>
147	                <Select value={category} onValueChange={setCategory}>
148	                  <SelectTrigger aria-required="true" className="w-full" id="support-category">
149	                    <SelectValue placeholder="Selecciona una categoría" />
150	                  </SelectTrigger>
151	                  <SelectContent>
152	                    <SelectGroup>
153	                      {categories.map((item) => (
154	                        <SelectItem key={item} value={item}>
155	                          {item}
156	                        </SelectItem>
157	                      ))}
158	                    </SelectGroup>
159	                  </SelectContent>
160	                </Select>
161	              </Field>
162	              <Field>
163	                <FieldLabel htmlFor="support-subject">
164	                  Asunto <RequiredMark />
165	                </FieldLabel>
166	                <Input
167	                  aria-required="true"
168	                  id="support-subject"
169	                  value={subject}
170	                  onChange={(event) => setSubject(event.target.value)}
171	                />
172	                <FieldDescription>Usa una frase breve para reconocer el caso después.</FieldDescription>
173	              </Field>
174	              <Field>
175	                <FieldLabel htmlFor="support-description">
176	                  Descripción <RequiredMark />
177	                </FieldLabel>
178	                <Textarea
179	                  aria-required="true"
180	                  id="support-description"
181	                  rows={6}
182	                  value={description}
183	                  onChange={(event) => setDescription(event.target.value)}
184	                />
185	              </Field>
186	            </FieldGroup>
187	          </div>
188	          <SheetActions>
189	            <Button type="button" variant="brand-secondary" onClick={close}>
190	              Cancelar
191	            </Button>
192	            <Button disabled={!complete} type="submit">
193	              <LifeBuoy data-icon="inline-start" /> Crear caso
194	            </Button>
195	          </SheetActions>
196	        </form>
197	      </SheetContent>
198	    </Sheet>
199	  );
200	}
201	
202	function TicketDetail({
203	  ticket,
204	  onBack,
205	  onUpdate,
206	}: {
207	  ticket: Ticket;
208	  onBack: () => void;
209	  onUpdate: (ticket: Ticket) => void;
210	}) {
211	  const [reply, setReply] = useState("");
212	
213	  function submit(event: FormEvent<HTMLFormElement>) {
214	    event.preventDefault();
215	    if (!reply.trim()) return;
216	    onUpdate({ ...ticket, comments: [...ticket.comments, reply.trim()], updatedAt: "ahora" });
217	    setReply("");
218	    toast.success("Respuesta enviada.");
219	  }
220	
221	  return (
222	    <div className="mx-auto flex max-w-4xl flex-col gap-4">
223	      <Button className="w-fit" onClick={onBack} size="sm" variant="brand-secondary">
224	        <ArrowLeft data-icon="inline-start" /> Todos los casos
225	      </Button>
226	      <Card variant="subtle">
227	        <CardHeader className="gap-3 border-b">
228	          <div className="flex flex-wrap items-start justify-between gap-3">
229	            <div className="flex min-w-0 flex-col gap-2">
230	              <div className="flex flex-wrap items-center gap-2">
231	                <Badge variant={statusVariant[ticket.status]}>{statusLabel[ticket.status]}</Badge>
232	                <span className="text-muted-foreground text-sm">{ticket.category}</span>
233	              </div>
234	              <CardTitle>{ticket.subject}</CardTitle>
235	              <CardDescription>
236	                {ticket.id} · actualizado {ticket.updatedAt}
237	              </CardDescription>
238	            </div>
239	            {ticket.status === "open" ? (
240	              <Button size="sm" variant="brand-secondary" onClick={() => onUpdate({ ...ticket, status: "resolved" })}>
241	                <CheckCircle2 data-icon="inline-start" /> Marcar como resuelto
242	              </Button>
243	            ) : null}
244	          </div>
245	        </CardHeader>
246	        <CardContent className="flex flex-col gap-4">
247	          <div className="ml-auto max-w-[85%] rounded-xl bg-primary px-4 py-3 text-primary-foreground">
248	            <p className="text-sm">{ticket.description}</p>
249	          </div>
250	          {ticket.comments.map((comment) => (
251	            <div className="max-w-[85%] rounded-xl bg-muted px-4 py-3" key={`${ticket.id}-${comment}`}>
252	              <p className="text-sm">{comment}</p>
253	            </div>
254	          ))}
255	        </CardContent>
256	      </Card>
257	      {ticket.status === "open" ? (
258	        <Card variant="subtle">
259	          <CardHeader>
260	            <CardTitle className="text-base">Añadir información</CardTitle>
261	          </CardHeader>
262	          <CardContent>
263	            <form className="flex flex-col gap-3" noValidate onSubmit={submit}>
264	              <Field>
265	                <FieldLabel htmlFor="support-reply">
266	                  Respuesta <RequiredMark />
267	                </FieldLabel>
268	                <Textarea
269	                  aria-required="true"
270	                  id="support-reply"
271	                  rows={4}
272	                  value={reply}
273	                  onChange={(event) => setReply(event.target.value)}
274	                />
275	              </Field>
276	              <div className="flex justify-end">
277	                <Button disabled={!reply.trim()} type="submit">
278	                  <Send data-icon="inline-start" /> Enviar respuesta
279	                </Button>
280	              </div>
281	            </form>
282	          </CardContent>
283	        </Card>
284	      ) : null}
285	    </div>
286	  );
287	}
288	
289	export function SupportPreview() {
290	  const [tickets, setTickets] = useState(initialTickets);
291	  const [query, setQuery] = useState("");
292	  const [status, setStatus] = useState<Status | "all">("all");
293	  const [page, setPage] = useState(1);
294	  const [dialogOpen, setDialogOpen] = useState(false);
295	  const [selectedId, setSelectedId] = useState<string | null>(null);
296	  const pageSize = 10;
297	  const selected = tickets.find((ticket) => ticket.id === selectedId);
298	  const filtered = useMemo(
299	    () =>
300	      tickets.filter((ticket) => {
301	        const term = query.trim().toLocaleLowerCase("es");
302	        return (
303	          (status === "all" || ticket.status === status) &&
304	          (!term || [ticket.subject, ticket.category].some((value) => value.toLocaleLowerCase("es").includes(term)))
305	        );
306	      }),
307	    [query, status, tickets],
308	  );
309	  const pageCount = Math.max(1, Math.ceil(filtered.length / pageSize));
310	  const safePage = Math.min(page, pageCount);
311	  const visible = filtered.slice((safePage - 1) * pageSize, safePage * pageSize);
312	
313	  if (selected)
314	    return (
315	      <TicketDetail
316	        ticket={selected}
317	        onBack={() => setSelectedId(null)}
318	        onUpdate={(updated) =>
319	          setTickets((current) => current.map((item) => (item.id === updated.id ? updated : item)))
320	        }
321	      />
322	    );
323	
324	  const metrics = [
325	    { label: "Abiertos", status: "open" as const, icon: CircleDot, description: "En espera de atención" },
326	    { label: "Resueltos", status: "resolved" as const, icon: CircleCheck, description: "Resueltos en el historial" },
327	    { label: "Cerrados", status: "closed" as const, icon: CircleX, description: "Sin acciones pendientes" },
328	  ];
329	  const hasFilters = Boolean(query || status !== "all");
330	  const clear = () => {
331	    setQuery("");
332	    setStatus("all");
333	    setPage(1);
334	  };
335	
336	  return (
337	    <>
338	      <div className="flex flex-col gap-4">
339	        <CollectionHeader
340	          description="Revisa tus casos abiertos y habla con el equipo de Zapi desde un único lugar."
341	          title="Soporte"
342	        />
343	        <div className="grid gap-4 md:grid-cols-3">
344	          {metrics.map(({ status: metricStatus, ...metric }) => (
345	            <MetricCard
346	              key={metric.label}
347	              {...metric}
348	              value={tickets.filter((ticket) => ticket.status === metricStatus).length}
349	            />
350	          ))}
351	        </div>
352	        <Card variant="subtle">
353	          <DataTableHeader
354	            search={{
355	              ariaLabel: "Buscar casos",
356	              placeholder: "Buscar casos...",
357	              value: query,
358	              onChange: (value) => {
359	                setQuery(value);
360	                setPage(1);
361	              },
362	            }}
363	            action={
364	              <Button size="sm" onClick={() => setDialogOpen(true)}>
365	                <Plus data-icon="inline-start" /> Nuevo caso
366	              </Button>
367	            }
368	          />
369	          <CardContent className="flex flex-col gap-4 px-0">
370	            <DataTableToolbar
371	              actions={
372	                hasFilters ? (
373	                  <Button size="sm" variant="outline" onClick={clear}>
374	                    <X data-icon="inline-start" /> Limpiar
375	                  </Button>
376	                ) : undefined
377	              }
378	            >
379	              <DataTableFilter
380	                ariaLabel="Filtrar por estado"
381	                label="Estado"
382	                value={status}
383	                onValueChange={(value) => {
384	                  setStatus(value as Status | "all");
385	                  setPage(1);
386	                }}
387	                options={[
388	                  { label: "Todos", value: "all" },
389	                  { label: "Abiertos", value: "open" },
390	                  { label: "Resueltos", value: "resolved" },
391	                  { label: "Cerrados", value: "closed" },
392	                ]}
393	              />
394	            </DataTableToolbar>
395	            <Table>
396	              <TableHeader>
397	                <TableRow>
398	                  <TableHead>Caso</TableHead>
399	                  <TableHead className="hidden md:table-cell">Categoría</TableHead>
400	                  <TableHead>Estado</TableHead>
401	                  <TableHead className="text-right">Acción</TableHead>
402	                </TableRow>
403	              </TableHeader>
404	              <TableBody>
405	                {visible.length ? (
406	                  visible.map((ticket) => (
407	                    <TableRow key={ticket.id}>
408	                      <TableCell>
409	                        <p className="font-medium">{ticket.subject}</p>
410	                        <p className="flex items-center gap-1 text-muted-foreground text-xs">
411	                          <MessageSquare className="size-3" /> {ticket.comments.length} respuestas
412	                        </p>
413	                      </TableCell>
414	                      <TableCell className="hidden md:table-cell">{ticket.category}</TableCell>
415	                      <TableCell>
416	                        <Badge variant={statusVariant[ticket.status]}>{statusLabel[ticket.status]}</Badge>
417	                      </TableCell>
418	                      <TableCell className="text-right">
419	                        <Button size="sm" variant="brand-secondary" onClick={() => setSelectedId(ticket.id)}>
420	                          <MessageSquare data-icon="inline-start" /> Ver caso
421	                        </Button>
422	                      </TableCell>
423	                    </TableRow>
424	                  ))
425	                ) : (
426	                  <TableRow>
427	                    <TableCell colSpan={4}>
428	                      <EmptyState
429	                        icon={hasFilters ? Search : LifeBuoy}
430	                        title={hasFilters ? "No hay coincidencias" : "Aún no tienes casos"}
431	                        description={hasFilters ? "Prueba con otros filtros." : "Crea un caso cuando necesites ayuda."}
432	                      />
433	                    </TableCell>
434	                  </TableRow>
435	                )}
436	              </TableBody>
437	            </Table>
438	            <TablePagination
439	              total={filtered.length}
440	              itemLabel="casos"
441	              rangeStart={filtered.length ? (safePage - 1) * pageSize + 1 : 0}
442	              rangeEnd={filtered.length ? (safePage - 1) * pageSize + visible.length : 0}
443	              canGoPrevious={safePage > 1}
444	              canGoNext={safePage < pageCount}
445	              onPreviousPage={() => setPage((current) => Math.max(1, current - 1))}
446	              onNextPage={() => setPage((current) => Math.min(pageCount, current + 1))}
447	            />
448	          </CardContent>
449	        </Card>
450	      </div>
451	      <TicketSheet
452	        open={dialogOpen}
453	        onOpenChange={setDialogOpen}
454	        onCreate={(ticket) => {
455	          setTickets((current) => [ticket, ...current]);
456	          setPage(1);
457	        }}
458	      />
459	    </>
460	  );
461	}
