"use client";

import { type FormEvent, useMemo, useState } from "react";

import {
  ArrowLeft,
  CheckCircle2,
  CircleCheck,
  CircleDot,
  CircleX,
  LifeBuoy,
  MessageSquare,
  Plus,
  Search,
  Send,
  X,
} from "lucide-react";
import { toast } from "sonner";

import { CollectionHeader } from "@/components/collection-header";
import { DataTableFilter, DataTableHeader, DataTableToolbar } from "@/components/data-table-controls";
import { EmptyState } from "@/components/empty-state";
import { MetricCard } from "@/components/metric-card";
import { SheetActions } from "@/components/sheet-actions";
import { TablePagination } from "@/components/table-pagination";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Field, FieldDescription, FieldGroup, FieldLabel } from "@/components/ui/field";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectGroup, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Sheet, SheetContent, SheetDescription, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Textarea } from "@/components/ui/textarea";

type Status = "open" | "resolved" | "closed";
type Ticket = {
  id: string;
  category: string;
  subject: string;
  description: string;
  status: Status;
  comments: string[];
  updatedAt: string;
};

const categories = ["Cuenta y acceso", "Publicación y canales", "Facturación y plan", "Otro problema"];
const initialTickets: Ticket[] = [
  {
    id: "SUP-1042",
    category: "Publicación y canales",
    subject: "La imagen no se muestra en la vista previa",
    description: "El archivo adjunto aparece vacío aunque está disponible en la biblioteca.",
    status: "open",
    comments: ["Estamos revisando el archivo y la conexión con el canal."],
    updatedAt: "4 ago 2026",
  },
  {
    id: "SUP-1038",
    category: "Cuenta y acceso",
    subject: "Necesito actualizar el rol de una persona",
    description: "Quiero permitir que una integrante administre los canales.",
    status: "resolved",
    comments: ["El rol ya se puede actualizar desde Teams."],
    updatedAt: "29 jul 2026",
  },
  {
    id: "SUP-1021",
    category: "Facturación y plan",
    subject: "Consulta sobre el límite de publicaciones",
    description: "¿Los borradores consumen el límite mensual?",
    status: "closed",
    comments: ["Los borradores no consumen el límite."],
    updatedAt: "12 jul 2026",
  },
];

const statusLabel: Record<Status, string> = { open: "Abierto", resolved: "Resuelto", closed: "Cerrado" };
const statusVariant: Record<Status, "info" | "success" | "secondary"> = {
  open: "info",
  resolved: "success",
  closed: "secondary",
};

function RequiredMark() {
  return (
    <span aria-hidden="true" className="text-destructive">
      *
    </span>
  );
}

function TicketSheet({
  open,
  onOpenChange,
  onCreate,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onCreate: (ticket: Ticket) => void;
}) {
  const [category, setCategory] = useState("");
  const [subject, setSubject] = useState("");
  const [description, setDescription] = useState("");
  const complete = Boolean(category && subject.trim() && description.trim());

  function close() {
    setCategory("");
    setSubject("");
    setDescription("");
    onOpenChange(false);
  }

  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!complete) {
      toast.error("Completa todos los campos obligatorios.");
      return;
    }
    onCreate({
      id: `SUP-${Date.now().toString().slice(-4)}`,
      category,
      subject: subject.trim(),
      description: description.trim(),
      status: "open",
      comments: [],
      updatedAt: "ahora",
    });
    toast.success("Caso creado.");
    close();
  }

  return (
    <Sheet open={open} onOpenChange={(next) => (next ? onOpenChange(true) : close())}>
      <SheetContent className="w-full gap-0 p-0 sm:max-w-xl" side="right">
        <SheetHeader className="border-b">
          <SheetTitle>Nuevo caso de soporte</SheetTitle>
          <SheetDescription>Describe lo que necesitas y conserva la conversación en este mismo caso.</SheetDescription>
        </SheetHeader>
        <form className="flex min-h-0 flex-1 flex-col" noValidate onSubmit={submit}>
          <div className="flex min-h-0 flex-1 flex-col gap-5 overflow-y-auto p-4">
            <FieldGroup>
              <Field>
                <FieldLabel htmlFor="support-category">
                  Categoría <RequiredMark />
                </FieldLabel>
                <Select value={category} onValueChange={setCategory}>
                  <SelectTrigger aria-required="true" className="w-full" id="support-category">
                    <SelectValue placeholder="Selecciona una categoría" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectGroup>
                      {categories.map((item) => (
                        <SelectItem key={item} value={item}>
                          {item}
                        </SelectItem>
                      ))}
                    </SelectGroup>
                  </SelectContent>
                </Select>
              </Field>
              <Field>
                <FieldLabel htmlFor="support-subject">
                  Asunto <RequiredMark />
                </FieldLabel>
                <Input
                  aria-required="true"
                  id="support-subject"
                  value={subject}
                  onChange={(event) => setSubject(event.target.value)}
                />
                <FieldDescription>Usa una frase breve para reconocer el caso después.</FieldDescription>
              </Field>
              <Field>
                <FieldLabel htmlFor="support-description">
                  Descripción <RequiredMark />
                </FieldLabel>
                <Textarea
                  aria-required="true"
                  id="support-description"
                  rows={6}
                  value={description}
                  onChange={(event) => setDescription(event.target.value)}
                />
              </Field>
            </FieldGroup>
          </div>
          <SheetActions>
            <Button type="button" variant="brand-secondary" onClick={close}>
              Cancelar
            </Button>
            <Button disabled={!complete} type="submit">
              <LifeBuoy data-icon="inline-start" /> Crear caso
            </Button>
          </SheetActions>
        </form>
      </SheetContent>
    </Sheet>
  );
}

function TicketDetail({
  ticket,
  onBack,
  onUpdate,
}: {
  ticket: Ticket;
  onBack: () => void;
  onUpdate: (ticket: Ticket) => void;
}) {
  const [reply, setReply] = useState("");

  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!reply.trim()) return;
    onUpdate({ ...ticket, comments: [...ticket.comments, reply.trim()], updatedAt: "ahora" });
    setReply("");
    toast.success("Respuesta enviada.");
  }

  return (
    <div className="mx-auto flex max-w-4xl flex-col gap-4">
      <Button className="w-fit" onClick={onBack} size="sm" variant="brand-secondary">
        <ArrowLeft data-icon="inline-start" /> Todos los casos
      </Button>
      <Card variant="subtle">
        <CardHeader className="gap-3 border-b">
          <div className="flex flex-wrap items-start justify-between gap-3">
            <div className="flex min-w-0 flex-col gap-2">
              <div className="flex flex-wrap items-center gap-2">
                <Badge variant={statusVariant[ticket.status]}>{statusLabel[ticket.status]}</Badge>
                <span className="text-muted-foreground text-sm">{ticket.category}</span>
              </div>
              <CardTitle>{ticket.subject}</CardTitle>
              <CardDescription>
                {ticket.id} · actualizado {ticket.updatedAt}
              </CardDescription>
            </div>
            {ticket.status === "open" ? (
              <Button size="sm" variant="brand-secondary" onClick={() => onUpdate({ ...ticket, status: "resolved" })}>
                <CheckCircle2 data-icon="inline-start" /> Marcar como resuelto
              </Button>
            ) : null}
          </div>
        </CardHeader>
        <CardContent className="flex flex-col gap-4">
          <div className="ml-auto max-w-[85%] rounded-xl bg-primary px-4 py-3 text-primary-foreground">
            <p className="text-sm">{ticket.description}</p>
          </div>
          {ticket.comments.map((comment) => (
            <div className="max-w-[85%] rounded-xl bg-muted px-4 py-3" key={`${ticket.id}-${comment}`}>
              <p className="text-sm">{comment}</p>
            </div>
          ))}
        </CardContent>
      </Card>
      {ticket.status === "open" ? (
        <Card variant="subtle">
          <CardHeader>
            <CardTitle className="text-base">Añadir información</CardTitle>
          </CardHeader>
          <CardContent>
            <form className="flex flex-col gap-3" noValidate onSubmit={submit}>
              <Field>
                <FieldLabel htmlFor="support-reply">
                  Respuesta <RequiredMark />
                </FieldLabel>
                <Textarea
                  aria-required="true"
                  id="support-reply"
                  rows={4}
                  value={reply}
                  onChange={(event) => setReply(event.target.value)}
                />
              </Field>
              <div className="flex justify-end">
                <Button disabled={!reply.trim()} type="submit">
                  <Send data-icon="inline-start" /> Enviar respuesta
                </Button>
              </div>
            </form>
          </CardContent>
        </Card>
      ) : null}
    </div>
  );
}

export function SupportPreview() {
  const [tickets, setTickets] = useState(initialTickets);
  const [query, setQuery] = useState("");
  const [status, setStatus] = useState<Status | "all">("all");
  const [page, setPage] = useState(1);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const pageSize = 10;
  const selected = tickets.find((ticket) => ticket.id === selectedId);
  const filtered = useMemo(
    () =>
      tickets.filter((ticket) => {
        const term = query.trim().toLocaleLowerCase("es");
        return (
          (status === "all" || ticket.status === status) &&
          (!term || [ticket.subject, ticket.category].some((value) => value.toLocaleLowerCase("es").includes(term)))
        );
      }),
    [query, status, tickets],
  );
  const pageCount = Math.max(1, Math.ceil(filtered.length / pageSize));
  const safePage = Math.min(page, pageCount);
  const visible = filtered.slice((safePage - 1) * pageSize, safePage * pageSize);

  if (selected)
    return (
      <TicketDetail
        ticket={selected}
        onBack={() => setSelectedId(null)}
        onUpdate={(updated) =>
          setTickets((current) => current.map((item) => (item.id === updated.id ? updated : item)))
        }
      />
    );

  const metrics = [
    { label: "Abiertos", status: "open" as const, icon: CircleDot, description: "En espera de atención" },
    { label: "Resueltos", status: "resolved" as const, icon: CircleCheck, description: "Resueltos en el historial" },
    { label: "Cerrados", status: "closed" as const, icon: CircleX, description: "Sin acciones pendientes" },
  ];
  const hasFilters = Boolean(query || status !== "all");
  const clear = () => {
    setQuery("");
    setStatus("all");
    setPage(1);
  };

  return (
    <>
      <div className="flex flex-col gap-4">
        <CollectionHeader
          description="Revisa tus casos abiertos y habla con el equipo de Zapi desde un único lugar."
          title="Soporte"
        />
        <div className="grid gap-4 md:grid-cols-3">
          {metrics.map(({ status: metricStatus, ...metric }) => (
            <MetricCard
              key={metric.label}
              {...metric}
              value={tickets.filter((ticket) => ticket.status === metricStatus).length}
            />
          ))}
        </div>
        <Card variant="subtle">
          <DataTableHeader
            search={{
              ariaLabel: "Buscar casos",
              placeholder: "Buscar casos...",
              value: query,
              onChange: (value) => {
                setQuery(value);
                setPage(1);
              },
            }}
            action={
              <Button size="sm" onClick={() => setDialogOpen(true)}>
                <Plus data-icon="inline-start" /> Nuevo caso
              </Button>
            }
          />
          <CardContent className="flex flex-col gap-4 px-0">
            <DataTableToolbar
              actions={
                hasFilters ? (
                  <Button size="sm" variant="outline" onClick={clear}>
                    <X data-icon="inline-start" /> Limpiar
                  </Button>
                ) : undefined
              }
            >
              <DataTableFilter
                ariaLabel="Filtrar por estado"
                label="Estado"
                value={status}
                onValueChange={(value) => {
                  setStatus(value as Status | "all");
                  setPage(1);
                }}
                options={[
                  { label: "Todos", value: "all" },
                  { label: "Abiertos", value: "open" },
                  { label: "Resueltos", value: "resolved" },
                  { label: "Cerrados", value: "closed" },
                ]}
              />
            </DataTableToolbar>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Caso</TableHead>
                  <TableHead className="hidden md:table-cell">Categoría</TableHead>
                  <TableHead>Estado</TableHead>
                  <TableHead className="text-right">Acción</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {visible.length ? (
                  visible.map((ticket) => (
                    <TableRow key={ticket.id}>
                      <TableCell>
                        <p className="font-medium">{ticket.subject}</p>
                        <p className="flex items-center gap-1 text-muted-foreground text-xs">
                          <MessageSquare className="size-3" /> {ticket.comments.length} respuestas
                        </p>
                      </TableCell>
                      <TableCell className="hidden md:table-cell">{ticket.category}</TableCell>
                      <TableCell>
                        <Badge variant={statusVariant[ticket.status]}>{statusLabel[ticket.status]}</Badge>
                      </TableCell>
                      <TableCell className="text-right">
                        <Button size="sm" variant="brand-secondary" onClick={() => setSelectedId(ticket.id)}>
                          <MessageSquare data-icon="inline-start" /> Ver caso
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))
                ) : (
                  <TableRow>
                    <TableCell colSpan={4}>
                      <EmptyState
                        icon={hasFilters ? Search : LifeBuoy}
                        title={hasFilters ? "No hay coincidencias" : "Aún no tienes casos"}
                        description={hasFilters ? "Prueba con otros filtros." : "Crea un caso cuando necesites ayuda."}
                      />
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
            <TablePagination
              total={filtered.length}
              itemLabel="casos"
              rangeStart={filtered.length ? (safePage - 1) * pageSize + 1 : 0}
              rangeEnd={filtered.length ? (safePage - 1) * pageSize + visible.length : 0}
              canGoPrevious={safePage > 1}
              canGoNext={safePage < pageCount}
              onPreviousPage={() => setPage((current) => Math.max(1, current - 1))}
              onNextPage={() => setPage((current) => Math.min(pageCount, current + 1))}
            />
          </CardContent>
        </Card>
      </div>
      <TicketSheet
        open={dialogOpen}
        onOpenChange={setDialogOpen}
        onCreate={(ticket) => {
          setTickets((current) => [ticket, ...current]);
          setPage(1);
        }}
      />
    </>
  );
}

